package com.joyintech.tams.cfets.trd.bond.dto;import io.swagger.annotations.ApiModel;import io.swagger.annotations.ApiModelProperty;import java.util.List;@ApiModel(value="当日报价列表查询条件",description="当日报价列表查询条件")public class DayPriceRequest {    @ApiModelProperty(name="pss",value="交易方向代码集合")    private List<String> pss;    @ApiModelProperty(name="finprodMarketIds",value="市场代码",example="[A,B]")    private List<String> finprodMarketIds;    @ApiModelProperty(name="mySideTrader",value="本方交易员")    private List<String> mySideTraders;    @ApiModelProperty(name="counterId",value="对手方")    private List<String> counterIds;    @ApiModelProperty(name="counterTrader",value="对手方交易员")    private List<String> counterTraders;    @ApiModelProperty(name="quoteId ",value="报价编号")    private String quoteId;    @ApiModelProperty(name="dayOfferStatus",value="交易状态 undo 未成交 done 已成交")    private String dayOfferStatus;    @ApiModelProperty(name="search",value="关键词")    private String search;    public List<String> getPss() {        return pss;    }    public void setPss(List<String> pss) {        this.pss = pss;    }    public List<String> getFinprodMarketIds() {        return finprodMarketIds;    }    public void setFinprodMarketIds(List<String> finprodMarketIds) {        this.finprodMarketIds = finprodMarketIds;    }    public List<String> getMySideTraders() {        return mySideTraders;    }    public void setMySideTraders(List<String> mySideTraders) {        this.mySideTraders = mySideTraders;    }    public List<String> getCounterTraders() {        return counterTraders;    }    public void setCounterTraders(List<String> counterTraders) {        this.counterTraders = counterTraders;    }    public List<String> getCounterIds() {        return counterIds;    }    public void setCounterIds(List<String> counterIds) {        this.counterIds = counterIds;    }    public String getQuoteId() {        return quoteId;    }    public void setQuoteId(String quoteId) {        this.quoteId = quoteId;    }    public String getSearch() {        return search;    }    public void setSearch(String search) {        this.search = search;    }    public String getDayOfferStatus() {        return dayOfferStatus;    }    public void setDayOfferStatus(String dayOfferStatus) {        this.dayOfferStatus = dayOfferStatus;    }}